-- New questions that fill gaps in the pre-medical banks, all original and checked:
-- * Organic chemistry structure questions (CHE-2001 on) and physics diagram questions (PHY-2001 on), each with a
--   figure drawn as a line diagram (questions.figure, migrations/0066).
-- * Figure reasoning for Logical Reasoning (LR-1001 on): series, grids, odd figure out, mirror and water images, paper
--   folding, counting triangles and squares. The options are the figures A to D drawn inside the question's figure.
-- * Verbal intelligence (LR-1101 on): analogies, odd one out, word skills.
-- They go in the MDCAT bank through their own chapter, and in the other banks through bank_questions below.
--
-- The Army Medical College bank ('amc', lib/banks.ts) holds the verbal and non-verbal intelligence tests that Army
-- medical cadets sit on top of the NUMS test. It lists the new reasoning questions above and these existing Logical
-- Reasoning questions, filed by kind of test.
-- The live database already has bank_questions without its old CHECK on bank ids (migrations/0070). A database built
-- from scratch runs this file before 0070, where the CHECK still stands and the 'amc' rows are skipped.
INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'amc', id, 'Verbal intelligence',
  CASE
    WHEN topic = 'Analogy' THEN 'Analogies'
    WHEN topic = 'Odd one out' THEN 'Odd one out'
    WHEN topic IN ('Number series', 'Letter series', 'Letter and number series', 'Letter, number and symbol series', 'Symbol series',
                   'Geometric progression', 'Wrong number in a series', 'Missing number', 'Alphabet positions') THEN 'Series'
    WHEN topic IN ('Coding', 'Coding and decoding', 'Code language', 'Coded relations') THEN 'Coding and decoding'
    WHEN topic IN ('Blood relations', 'Direction problems') THEN 'Relations and directions'
    WHEN topic IN ('Ranking', 'Ordering', 'Ordering puzzles', 'Seating arrangement') THEN 'Ordering and ranking'
    WHEN topic IN ('Calendar problems', 'Clock problems') THEN 'Calendars and clocks'
  END
FROM questions
WHERE subject = 'Logical Reasoning' AND paper IS NULL AND topic IN (
  'Analogy', 'Odd one out', 'Number series', 'Letter series', 'Letter and number series', 'Letter, number and symbol series',
  'Symbol series', 'Geometric progression', 'Wrong number in a series', 'Missing number', 'Alphabet positions', 'Coding',
  'Coding and decoding', 'Code language', 'Coded relations', 'Blood relations', 'Direction problems', 'Ranking', 'Ordering',
  'Ordering puzzles', 'Seating arrangement', 'Calendar problems', 'Clock problems');

INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'amc', id, 'Non-verbal intelligence', 'Cubes and dice' FROM questions
WHERE subject = 'Logical Reasoning' AND paper IS NULL AND topic IN ('Cubes', 'Cubes and dice');

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
