3 Q 477.4 138.2, 476.2 138.5 L 479.4 144.0 L 477.5 144.0 M 472.3 137.3 L 474.4 137.3 Q 475.6 137.3, 476.3 136.7 Q 477.0 136.1, 477.0 135.0 Q 477.0 133.9, 476.3 133.3 Q 475.6 132.7, 474.4 132.7 L 472.3 132.7 L 472.3 137.3 '' fill=''#000000''/><path d=''M 662.4,77.3 L 700.2,99.3'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 662.4,77.3 L 682.8,42.1'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 662.4,77.3 L 642.1,42.0'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 662.4,77.3 L 624.4,99.0'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 702.1 106.6 Q 702.1 100.6, 704.9 97.5 Q 707.7 94.3, 713.1 94.3 Q 718.1 94.3, 720.7 97.8 L 718.5 99.7 Q 716.5 97.1, 713.1 97.1 Q 709.4 97.1, 707.5 99.6 Q 705.6 102.0, 705.6 106.6 Q 705.6 111.4, 707.6 113.8 Q 709.6 116.3, 713.5 116.3 Q 716.1 116.3, 719.2 114.7 L 720.2 117.2 Q 718.9 118.0, 717.0 118.5 Q 715.1 119.0, 713.0 119.0 Q 707.7 119.0, 704.9 115.8 Q 702.1 112.6, 702.1 106.6 '' fill=''#000000''/><path d=''M 723.2 92.9 L 726.3 92.9 L 726.3 118.7 L 723.2 118.7 L 723.2 92.9 '' fill=''#000000''/><path d=''M 681.4 16.2 L 684.7 16.2 L 684.7 26.4 L 697.0 26.4 L 697.0 16.2 L 700.3 16.2 L 700.3 40.3 L 697.0 40.3 L 697.0 29.1 L 684.7 29.1 L 684.7 40.3 L 681.4 40.3 L 681.4 16.2 '' fill=''#000000''/><path d=''M 624.7 16.0 L 628.0 16.0 L 628.0 26.2 L 640.3 26.2 L 640.3 16.0 L 643.6 16.0 L 643.6 40.1 L 640.3 40.1 L 640.3 29.0 L 628.0 29.0 L 628.0 40.1 L 624.7 40.1 L 624.7 16.0 '' fill=''#000000''/><path d=''M 603.7 93.5 L 607.0 93.5 L 607.0 103.7 L 619.3 103.7 L 619.3 93.5 L 622.6 93.5 L 622.6 117.6 L 619.3 117.6 L 619.3 106.4 L 607.0 106.4 L 607.0 117.6 L 603.7 117.6 L 603.7 93.5 '' fill=''#000000''/><path d=''M 661.4 141.7 Q 661.5 141.7, 662.1 142.0 Q 662.7 142.2, 663.4 142.4 Q 664.0 142.5, 664.7 142.5 Q 665.9 142.5, 666.6 142.0 Q 667.3 141.4, 667.3 140.3 Q 667.3 139.6, 666.9 139.2 Q 666.6 138.8, 666.1 138.5 Q 665.5 138.3, 664.6 138.0 Q 663.5 137.7, 662.8 137.4 Q 662.1 137.1, 661.7 136.4 Q 661.2 135.7, 661.2 134.5 Q 661.2 132.9, 662.3 131.9 Q 663.4 131.0, 665.5 131.0 Q 667.0 131.0, 668.7 131.7 L 668.3 133.0 Q 666.7 132.4, 665.6 132.4 Q 664.3 132.4, 663.6 132.9 Q 663.0 133.4, 663.0 134.3 Q 663.0 135.0, 663.3 135.4 Q 663.7 135.8, 664.2 136.1 Q 664.7 136.3, 665.6 136.6 Q 666.7 136.9, 667.4 137.3 Q 668.1 137.6, 668.6 138.4 Q 669.1 139.1, 669.1 140.3 Q 669.1 142.1, 667.9 143.1 Q 666.7 144.0, 664.8 144.0 Q 663.6 144.0, 662.8 143.7 Q 661.9 143.5, 660.9 143.1 L 661.4 141.7 '' fill=''#000000''/></svg>', '["P", "Q", "R", "S"]', 3, 'In SN2 the OH⁻ attacks the carbon from the side opposite the chlorine in one step. Bulky groups around that carbon get in the way. Chloromethane (S) has only small hydrogens around the carbon, so it reacts fastest.', '{"0": "Three methyl groups block the back of the carbon in 2-chloro-2-methylpropane, so it hardly reacts by SN2 at all.", "1": "Two methyl groups crowd the carbon in 2-chloropropane and slow the attack.", "2": "Chloroethane has one methyl group near the reacting carbon, so it is slower than chloromethane."}', 1),
  ('CHE-2040', 'Chemistry', 'Alkyl halides', 'Stereochemistry of SN2', 'hard', 'Markhor Prep original question', 'The bromoalkane shown, a single optical isomer, reacts with aqueous sodium hydroxide by an SN2 mechanism. Which describes the product?', '<svg version=''1.1'' xmlns=''http://www.w3.org/2000/svg'' width=''300px'' height=''180px'' viewBox=''0 0 300 180''><path d=''M 183.7,114.3 L 183.4,114.7'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 186.8,115.8 L 186.3,116.7'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 190.0,117.3 L 189.2,118.7'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 193.2,118.8 L 192.1,120.7'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 196.3,120.4 L 195.0,122.6'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 199.5,121.9 L 197.9,124.6'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 202.7,123.4 L 200.8,126.6'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 205.9,124.9 L 203.8,128.6'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 209.0,126.4 L 206.7,130.5'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 212.2,128.0 L 209.6,132.5'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 215.4,129.5 L 212.5,134.5'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 218.5,131.0 L 215.4,136.5'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 221.7,132.5 L 218.3,138.4'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 224.9,134.0 L 221.2,140.4'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 228.1,135.6 L 224.1,142.4'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 231.2,137.1 L 227.0,144.4'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 234.4,138.6 L 229.9,146.3'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 237.6,140.1 L 232.9,148.3'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 240.7,141.6 L 235.8,150.3'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 243.9,143.2 L 238.7,152.3'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 247.1,144.7 L 241.6,154.3'' style=''fill:none;stroke:#000000;stroke-width:1.0px;'' /><path d=''M 180.5,112.8 L 180.4,55.7'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 180.5,112.8 L 116.8,149.7'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 116.8,149.7 L 52.9,113.0'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 180.5,109.9 L 180.5,112.8 L 177.3,114.6'' style=''fill:none;stroke:#000000;stroke-width:2.0px;stroke-miterlimit:10;'' /><path d=''M 120.0,147.9 L 116.8,149.7 L 113.6,147.9'' style=''fill:none;stroke:#000000;stroke-width:2.0px;stroke-miterlimit:10;'' /><path d=''M 184.5 38.4 Q 187.2 39.1, 188.6 40.8 Q 190.0 42.5, 190.0 44.9 Q 190.0 48.8, 187.4 51.1 Q 185.0 53.3, 180.2 53.3 L 170.7 53.3 L 170.7 24.9 L 179.1 24.9 Q 183.9 24.9, 186.4 26.9 Q 188.8 28.9, 188.8 32.5 Q 188.8 36.7, 184.5 38.4 M 174.5 28.1 L 174.5 37.0 L 179.1 37.0 Q 181.9 37.0, 183.3 35.9 Q 184.8 34.7, 184.8 32.5 Q 184.8 28.1, 179.1 28.1 L 174.5 28.1 M 180.2 50.1 Q 183.0 50.1, 184.5 48.7 Q 186.0 47.4, 186.0 44.9 Q 186.0 42.6, 184.3 41.4 Q 182.7 40.2, 179.6 40.2 L 174.5 40.2 L 174.5 50.1 L 180.2 50.1 '' fill=''#000000''/><path d=''M 196.4 32.7 L 196.8 35.5 Q 199.0 32.3, 202.5 32.3 Q 203.6 32.3, 205.1 32.7 L 204.5 36.1 Q 202.8 35.7, 201.9 35.7 Q 200.2 35.7, 199.1 36.4 Q 198.0 37.0, 197.1 38.6 L 197.1 53.3 L 193.3 53.3 L 193.3 32.7 L 196.4 32.7 '' fill=''#000000''/></svg>', '["An equal mixture of both optical isomers of butan-2-ol", "Butan-2-ol with the same configuration as the starting material", "But-2-ene as the only product", "Butan-2-ol with the opposite (inverted) configuration"]', 3, 'In SN2 the hydroxide attacks from the side opposite the leaving bromide, in one step. The three other groups flip over like an umbrella in the wind, so the product has the inverted configuration (Walden inversion).', '{"0": "A racemic mixture is typical of SN1, where a flat carbocation can be attacked from either side.", "1": "Backside attack in SN2 always turns the configuration over. It is never kept the same.", "2": "Aqueous NaOH mainly causes substitution. Elimination is favoured by alcoholic KOH and heat."}', 1)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-2041', 'Chemistry', 'Alkyl halides', 'Elimination reactions', 'moderate', 'Markhor Prep original question', 'The compound shown is heated with alcoholic potassium hydroxide. What is the major organic product?', '<svg version=''1.1'' xmlns=''http://www.w3.org/2000/svg'' width=''300px'' height=''180px'' viewBox=''0 0 300 180''><path d=''M 42.9,111.8 L 114.3,153.0'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 114.3,153.0 L 185.7,111.7'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 185.7,111.7 L 226.8,40.3'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 185.7,111.7 L 257.1,152.9'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 185.7,111.7 L 153.0,55.3'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 110.7,150.9 L 114.3,153.0 L 117.9,150.9'' style=''fill:none;stroke:#000000;stroke-width:2.0px;stroke-miterlimit:10;'' /><path d=''M 129.6 39.6 Q 132.3 40.4, 133.7 42.1 Q 135.1 43.7, 135.1 46.2 Q 135.1 50.1, 132.6 52.3 Q 130.1 54.5, 125.4 54.5 L 115.9 54.5 L 115.9 26.2 L 124.2 26.2 Q 129.1 26.2, 131.5 28.2 Q 133.9 30.1, 133.9 33.7 Q 133.9 38.0, 129.6 39.6 M 119.7 29.4 L 119.7 38.3 L 124.2 38.3 Q 127.0 38.3, 128.5 37.2 Q 129.9 36.0, 129.9 33.7 Q 129.9 29.4, 124.2 29.4 L 119.7 29.4 M 125.4 51.3 Q 128.1 51.3, 129.6 50.0 Q 131.1 48.7, 131.1 46.2 Q 131.1 43.8, 129.5 42.7 Q 127.9 41.5, 124.8 41.5 L 119.7 41.5 L 119.7 51.3 L 125.4 51.3 '' fill=''#000000''/><path d=''M 141.5 34.0 L 142.0 36.8 Q 144.1 33.6, 147.7 33.6 Q 148.8 33.6, 150.3 34.0 L 149.7 37.4 Q 148.0 37.0, 147.0 37.0 Q 145.3 37.0, 144.2 37.6 Q 143.1 38.3, 142.3 39.8 L 142.3 54.5 L 138.5 54.5 L 138.5 34.0 L 141.5 34.0 '' fill=''#000000''/></svg>', '["2-methylbut-1-ene", "2-methylbut-2-ene", "3-methylbut-1-ene", "2-methylbutan-2-ol"]', 1, 'Alcoholic KOH removes HBr (dehydrohalogenation). Losing an H from the –CH₂– gives 2-methylbut-2-ene, which has three alkyl groups on its C=C. Losing an H from a –CH₃ gives 2-methylbut-1-ene, with two. The more substituted alkene is more stable and is the major product (Saytzeff''s rule).', '{"0": "2-methylbut-1-ene forms, but as the minor product because its C=C is less substituted.", "2": "The double bond can only form next to the carbon that carried Br. 3-methylbut-1-ene would need a C=C away from that carbon.", "3": "The alcohol is the substitution product, which is favoured by aqueous, not alcoholic, KOH."}', 1),
  ('CHE-2042', 'Chemistry', 'Alcohols and phenols', 'Naming alcohols', 'moderate', 'Markhor Prep original question', 'What is the IUPAC name of the alcohol shown?', '<svg version=''1.1'' xmlns=''http://www.w3.org/2000/svg'' width=''300px'' height=''180px'' viewBox=''0 0 300 180''><path d=''M 36.0,145.8 L 93.1,113.0'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 93.1,113.0 L 93.2,64.2'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 93.1,113.0 L 150.0,146.1'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 150.0,146.1 L 207.1,113.3'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 207.1,113.3 L 264.0,146.3'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 207.1,113.3 L 207.2,47.5'' style=''fill:none;stroke:#000000;stroke-width:2.0px;'' /><path d=''M 147.2,144.4 L 150.0,146.1 L 152.9,144.4'' style=''fill:none;stroke:#000000;stroke-width:2.0px;stroke-miterlimit:10;'' /><path d=''M 80.2 47.3 Q 80.2 40.5, 83.6 36.7 Q 86.9 32.9, 93.2 32.9 Q 99.5 32.9, 102.8 36.7 Q 106.2 40.5, 106.2 47.3 Q 106.2 54.2, 102.8 58.1 Q 99.4 62.0, 93.2 62.0 Q 87.0 62.0, 83.6 58.1 Q 80.2 54.2, 80.2 47.3 M 93.2 58.8 Q 97.5 58.8, 99.8 55.9 Q 102.2 53.0, 102.2 47.3 Q 102.2 41.7, 99.8 38.9 Q 97.5 36.1, 93.2 36.1 Q 88.9 36.1, 86.5 38.9 Q 84.2 41.7, 84.2 47.3 Q 84.2 53.0, 86.5 55.9 Q 88.9 58.8, 93.2 58.8 '' fill=''#000000''/><path d=''M 110.6 33.2 L 114.5 33.2 L 114.5 45.3 L 128.9 45.3 L 128.9 33.2 L 132.8 33.2 L 132.8 61.5 L 128.9 61.5 L 128.9 48.5 L 114.5 48.5 L 114.5 61.5 L 110.6 61.5 L 110.6 33.2 '' fill=''#000000''/></svg>', '["2-methylpentan-4-ol", "4-methylhexan-2-ol", "4-methylpentan-2-ol", "1,3-dimethylbutan-1-ol"]', 2, 'The longest chain carrying the –OH has five carbons (pentanol). Numbering gives the –OH the lowest number, 2, which puts the methyl group on C4: 4-methylpentan-2-ol.', '{"0": "The –OH group gets priority for the lowest number, so the name must be pentan-2-ol, not pentan-4-ol.", "1": "The chain has five carbons plus a methyl branch, not six in a row.", "3": "Calling the end carbons ''methyl'' groups misses the longest chain, which has five carbons."}', 1),
