) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-2004', 'Physics', 'Force and motion', 'Displacement–time graphs', 'moderate', 'Markhor Prep original question', 'Using the displacement–time graph, what is the cyclist''s average velocity over the whole 7 s?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''420'' height=''260'' viewBox=''0 0 420 260''><line x1=''58.0'' y1=''214.0'' x2=''408.0'' y2=''214.0'' stroke=''#000'' stroke-width=''1.6'' stroke-linecap=''round''/><polygon points=''400.6,217.1 408.0,214.0 400.6,210.9'' fill=''#000'' stroke=''#000'' stroke-width=''1.6'' stroke-linejoin=''round'' stroke-linecap=''round''/><line x1=''58.0'' y1=''214.0'' x2=''58.0'' y2=''12.0'' stroke=''#000'' stroke-width=''1.6'' stroke-linecap=''round''/><polygon points=''61.1,19.4 58.0,12.0 54.9,19.4'' fill=''#000'' stroke=''#000'' stroke-width=''1.6'' stroke-linejoin=''round'' stroke-linecap=''round''/><line x1=''100.2'' y1=''210.0'' x2=''100.2'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''100.2'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>1</text><line x1=''142.5'' y1=''210.0'' x2=''142.5'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''142.5'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>2</text><line x1=''184.8'' y1=''210.0'' x2=''184.8'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''184.8'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>3</text><line x1=''227.0'' y1=''210.0'' x2=''227.0'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''227.0'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>4</text><line x1=''269.2'' y1=''210.0'' x2=''269.2'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''269.2'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>5</text><line x1=''311.5'' y1=''210.0'' x2=''311.5'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''311.5'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>6</text><line x1=''353.8'' y1=''210.0'' x2=''353.8'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''353.8'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>7</text><line x1=''54.0'' y1=''182.6'' x2=''62.0'' y2=''182.6'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''48.0'' y=''182.6'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>2</text><line x1=''54.0'' y1=''151.3'' x2=''62.0'' y2=''151.3'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''48.0'' y=''151.3'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>4</text><line x1=''54.0'' y1=''119.9'' x2=''62.0'' y2=''119.9'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''48.0'' y=''119.9'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>6</text><line x1=''54.0'' y1=''88.6'' x2=''62.0'' y2=''88.6'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''48.0'' y=''88.6'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>8</text><line x1=''54.0'' y1=''57.2'' x2=''62.0'' y2=''57.2'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''48.0'' y=''57.2'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>10</text><text x=''227.0'' y=''248.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>time / s</text><text x=''16'' y=''116.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' transform=''rotate(-90 16 116.0)'' fill=''#000''>displacement / m</text><polyline points=''58.0,214.0 142.5,57.2 269.2,57.2 353.8,214.0'' fill=''none'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''91.8'' y=''115.2'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-style=''italic''>P</text><text x=''205.9'' y=''38.4'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-style=''italic''>Q</text><text x=''324.2'' y=''115.2'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-style=''italic''>R</text></svg>', '["2.9 m s⁻¹", "0 m s⁻¹", "5 m s⁻¹", "1.4 m s⁻¹"]', 1, 'Average velocity = total displacement ÷ total time. The cyclist ends where they started (displacement 0 at t = 7 s), so the average velocity is 0 ÷ 7 = 0. The average speed is not zero: 20 m ÷ 7 s ≈ 2.9 m s⁻¹.', '{"0": "2.9 m s⁻¹ is the average speed (distance 20 m ÷ 7 s). Velocity uses displacement, which is zero here.", "2": "5 m s⁻¹ is the speed during parts P and R only.", "3": "This divides the greatest displacement, 10 m, by 7 s. The final displacement is zero."}', 1),
  ('PHY-2005', 'Physics', 'Vectors and equilibrium', 'Adding perpendicular vectors', 'easy', 'Markhor Prep original question', 'Two forces of 8 N and 6 N act at right angles on point O, as shown. What is the size of their resultant?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''300'' height=''230'' viewBox=''0 0 300 230''><line x1=''60.0'' y1=''190.0'' x2=''240.0'' y2=''190.0'' stroke=''#000'' stroke-width=''2.4'' stroke-linecap=''round''/><polygon points=''230.8,193.9 240.0,190.0 230.8,186.1'' fill=''#000'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''155.0'' y=''208.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''15'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>8 N</text><line x1=''60.0'' y1=''190.0'' x2=''60.0'' y2=''55.0'' stroke=''#000'' stroke-width=''2.4'' stroke-linecap=''round''/><polygon points=''63.9,64.2 60.0,55.0 56.1,64.2'' fill=''#000'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''36.0'' y=''120.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''15'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>6 N</text><line x1=''240.0'' y1=''190.0'' x2=''240.0'' y2=''55.0'' stroke=''#000'' stroke-width=''1.3'' stroke-linecap=''round'' stroke-dasharray=''5 4''/><line x1=''60.0'' y1=''55.0'' x2=''240.0'' y2=''55.0'' stroke=''#000'' stroke-width=''1.3'' stroke-linecap=''round'' stroke-dasharray=''5 4''/><circle cx=''60.0'' cy=''190.0'' r=''4'' fill=''#000''/><text x=''50.0'' y=''202.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>O</text></svg>', '["10 N", "14 N", "2 N", "48 N"]', 0, 'For perpendicular forces the resultant is found by Pythagoras: √(8² + 6²) = √(64 + 36) = √100 = 10 N.', '{"1": "14 N would be right only if the forces acted in the same direction.", "2": "2 N would be right only if the forces acted in opposite directions.", "3": "Forces are added as vectors, not multiplied."}', 1),
  ('PHY-2006', 'Physics', 'Vectors and equilibrium', 'Rectangular components', 'moderate', 'Markhor Prep original question', 'A force of 20 N acts at 30° above the horizontal, as shown. What are its horizontal and vertical components?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''300'' height=''220'' viewBox=''0 0 300 220''><line x1=''50.0'' y1=''180.0'' x2=''197.2'' y2=''95.0'' stroke=''#000'' stroke-width=''2.6'' stroke-linecap=''round''/><polygon points=''191.2,103.0 197.2,95.0 187.3,96.2'' fill=''#000'' stroke=''#000'' stroke-width=''2.6'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''110.0'' y=''105.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''15'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>F = 20 N</text><line x1=''50.0'' y1=''180.0'' x2=''270.0'' y2=''180.0'' stroke=''#000'' stroke-width=''1.3'' stroke-linecap=''round'' stroke-dasharray=''5 4''/><path d=''M 105 180 A 55 55 0 0 0 97.6 152.5'' fill=''none'' stroke=''#000'' stroke-width=''1.5'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''122.0'' y=''166.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>30°</text><circle cx=''50.0'' cy=''180.0'' r=''4'' fill=''#000''/></svg>', '["10 N horizontal, 17.3 N vertical", "17.3 N horizontal, 10 N vertical", "20 N horizontal, 0 N vertical", "14.1 N horizontal, 14.1 N vertical"]', 1, 'Horizontal = F cos 30° = 20 × 0.866 = 17.3 N. Vertical = F sin 30° = 20 × 0.5 = 10 N. The component next to the angle uses cos.', '{"0": "This swaps sin and cos. The angle is measured from the horizontal, so the horizontal part uses cos 30°.", "2": "A force at an angle always has a vertical part as well, unless the angle is zero.", "3": "Equal components happen only at 45°."}', 1),
  ('PHY-2007', 'Physics', 'Force and motion', 'Projectile motion', 'moderate', 'Markhor Prep original question', 'A ball is kicked from level ground at 20 m s⁻¹ at 30° above the horizontal (g = 10 m s⁻², no air resistance). What is its maximum height?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''430'' height=''150'' viewBox=''0 0 430 150''><line x1=''30.0'' y1=''115.0'' x2=''410.0'' y2=''115.0'' stroke=''#000'' stroke-width=''1.6'' stroke-linecap=''round''/><polyline points=''40.0,115.0 48.5,110.2 57.0,105.7 65.5,101.4 74.0,97.3 82.5,93.5 91.0,90.0 99.5,86.7 108.0,83.6 116.5,80.8 125.0,78.2 133.5,75.9 142.0,73.8 150.5,71.9 159.0,70.3 167.5,69.0 176.0,67.9 184.5,67.0 193.0,66.4 201.5,66.0 210.0,65.9 218.5,66.0 227.0,66.4 235.5,67.0 244.0,67.9 252.5,69.0 261.0,70.3 269.5,71.9 278.0,73.8 286.5,75.9 295.0,78.2 303.5,80.8 312.0,83.6 320.5,86.7 329.0,90.0 337.5,93.5 346.0,97.3 354.5,101.4 363.0,105.7 371.5,110.2 380.0,115.0'' fill=''none'' stroke=''#000'' stroke-width=''2.2'' stroke-linejoin=''round'' stroke-linecap=''round'' stroke-dasharray=''7 5''/><line x1=''40.0'' y1=''115.0'' x2=''92.0'' y2=''85.0'' stroke=''#000'' stroke-width=''2.4'' stroke-linecap=''round''/><polygon points=''85.9,93.0 92.0,85.0 82.0,86.2'' fill=''#000'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''10.0'' y=''65.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''start'' dominant-baseline=''middle'' fill=''#000''>20 m s⁻¹</text><path d=''M 74 115 A 34 34 0 0 0 69.4 98.0'' fill=''none'' stroke=''#000'' stroke-width=''1.3'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''90.0'' y=''106.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''12'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>30°</text><circle cx=''40.0'' cy=''115.0'' r=''4'' fill=''#000''/></svg>', '["10 m", "20 m", "2.5 m", "5 m"]', 3, 'Only the vertical part of the velocity matters for height: u sin 30° = 20 × 0.5 = 10 m s⁻¹. At the top this is zero, so H = (u sin θ)² ÷ 2g = 100 ÷ 20 = 5 m.', '{"0": "This forgets to halve: H = v² ÷ 2g, not v² ÷ g.", "1": "This uses the full 20 m s⁻¹ as if the ball were kicked straight up, then forgets to square properly.", "2": "This halves the answer twice. (10)² ÷ (2 × 10) = 5 m."}', 1)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-2008', 'Physics', 'Force and motion', 'Projectile motion', 'moderate', 'Markhor Prep original question', 'For the same kick (20 m s⁻¹ at 30°, g = 10 m s⁻²), what is the horizontal range of the ball?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''430'' height=''150'' viewBox=''0 0 430 150''><line x1=''30.0'' y1=''115.0'' x2=''410.0'' y2=''115.0'' stroke=''#000'' stroke-width=''1.6'' stroke-linecap=''round''/><polyline points=''40.0,115.0 48.5,110.2 57.0,105.7 65.5,101.4 74.0,97.3 82.5,93.5 91.0,90.0 99.5,86.7 108.0,83.6 116.5,80.8 125.0,78.2 133.5,75.9 142.0,73.8 150.5,71.9 159.0,70.3 167.5,69.0 176.0,67.9 184.5,67.0 193.0,66.4 201.5,66.0 210.0,65.9 218.5,66.0 227.0,66.4 235.5,67.0 244.0,67.9 252.5,69.0 261.0,70.3 269.5,71.9 278.0,73.8 286.5,75.9 295.0,78.2 303.5,80.8 312.0,83.6 320.5,86.7 329.0,90.0 337.5,93.5 346.0,97.3 354.5,101.4 363.0,105.7 371.5,110.2 380.0,115.0'' fill=''none'' stroke=''#000'' stroke-width=''2.2'' stroke-linejoin=''round'' stroke-linecap=''round'' stroke-dasharray=''7 5''/><line x1=''40.0'' y1=''115.0'' x2=''92.0'' y2=''85.0'' stroke=''#000'' stroke-width=''2.4'' stroke-linecap=''round''/><polygon points=''85.9,93.0 92.0,85.0 82.0,86.2'' fill=''#000'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''10.0'' y=''65.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''start'' dominant-baseline=''middle'' fill=''#000''>20 m s⁻¹</text><path d=''M 74 115 A 34 34 0 0 0 69.4 98.0'' fill=''none'' stroke=''#000'' stroke-width=''1.3'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''90.0'' y=''106.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''12'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>30°</text><circle cx=''40.0'' cy=''115.0'' r=''4'' fill=''#000''/></svg>', '["40 m", "20 m", "about 34.6 m", "about 17.3 m"]', 2, 'R = u² sin 2θ ÷ g = 400 × sin 60° ÷ 10 = 400 × 0.866 ÷ 10 ≈ 34.6 m. Check: time of flight = 2 × 10 ÷ 10 = 2 s, and the horizontal speed is 20 cos 30° ≈ 17.3 m s⁻¹, so 17.3 × 2 ≈ 34.6 m.', '{"0": "40 m is the maximum range, which needs a 45° launch.", "1": "This uses sin 30° instead of sin 60° in the range formula.", "3": "This is the horizontal distance covered in only 1 s, half the flight time."}', 1),
  ('PHY-2009', 'Physics', 'Work and energy', 'Work from a force–extension graph', 'moderate', 'Markhor Prep original question', 'The graph shows the force needed to stretch a spring. How much work is done in stretching it by 0.10 m?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''420'' height=''260'' viewBox=''0 0 420 260''><line x1=''58.0'' y1=''214.0'' x2=''408.0'' y2=''214.0'' stroke=''#000'' stroke-width=''1.6'' stroke-linecap=''round''/><polygon points=''400.6,217.1 408.0,214.0 400.6,210.9'' fill=''#000'' stroke=''#000'' stroke-width=''1.6'' stroke-linejoin=''round'' stroke-linecap=''round''/><line x1=''58.0'' y1=''214.0'' x2=''58.0'' y2=''12.0'' stroke=''#000'' stroke-width=''1.6'' stroke-linecap=''round''/><polygon points=''61.1,19.4 58.0,12.0 54.9,19.4'' fill=''#000'' stroke=''#000'' stroke-width=''1.6'' stroke-linejoin=''round'' stroke-linecap=''round''/><line x1=''114.3'' y1=''210.0'' x2=''114.3'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''114.3'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>0.02</text><line x1=''170.7'' y1=''210.0'' x2=''170.7'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''170.7'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>0.04</text><line x1=''227.0'' y1=''210.0'' x2=''227.0'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''227.0'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>0.06</text><line x1=''283.3'' y1=''210.0'' x2=''283.3'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''283.3'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>0.08</text><line x1=''339.7'' y1=''210.0'' x2=''339.7'' y2=''218.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''339.7'' y=''230.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>0.1</text><line x1=''54.0'' y1=''174.8'' x2=''62.0'' y2=''174.8'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''48.0'' y=''174.8'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>5</text><line x1=''54.0'' y1=''135.6'' x2=''62.0'' y2=''135.6'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''48.0'' y=''135.6'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>10</text><line x1=''54.0'' y1=''96.4'' x2=''62.0'' y2=''96.4'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''48.0'' y=''96.4'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>15</text><line x1=''54.0'' y1=''57.2'' x2=''62.0'' y2=''57.2'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><text x=''48.0'' y=''57.2'' font-family=''Helvetica, Arial, sans-serif'' font-size=''13'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>20</text><text x=''227.0'' y=''248.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>extension / m</text><text x=''16'' y=''116.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' transform=''rotate(-90 16 116.0)'' fill=''#000''>force / N</text><polyline points=''58.0,214.0 339.7,57.2'' fill=''none'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><line x1=''339.7'' y1=''57.2'' x2=''339.7'' y2=''214.0'' stroke=''#000'' stroke-width=''1.2'' stroke-linecap=''round'' stroke-dasharray=''4 4''/><line x1=''339.7'' y1=''57.2'' x2=''58.0'' y2=''57.2'' stroke=''#000'' stroke-width=''1.2'' stroke-linecap=''round'' stroke-dasharray=''4 4''/></svg>', '["2.0 J", "1.0 J", "0.5 J", "200 J"]', 1, 'Work done is the area under the force–extension graph. The area is a triangle: ½ × 0.10 m × 20 N = 1.0 J.', '{"0": "This multiplies 20 N by 0.10 m without halving. The force rises from 0, so the area is a triangle.", "2": "This halves the answer twice.", "3": "This divides the force by the extension, which gives the spring constant (200 N/m), not the work."}', 1),
  ('PHY-2010', 'Physics', 'Fluid dynamics', 'Equation of continuity', 'easy', 'Markhor Prep original question', 'Water flows steadily through the pipe shown. It enters the wide part (area 6 cm²) at 3 m s⁻¹. What is its speed in the narrow part (area 2 cm²)?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''440'' height=''170'' viewBox=''0 0 440 170''><polyline points=''20.0,25.0 200.0,25.0 240.0,55.0 420.0,55.0'' fill=''none'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><polyline points=''20.0,145.0 200.0,145.0 240.0,115.0 420.0,115.0'' fill=''none'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''110.0'' y=''85.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>A = 6 cm²</text><text x=''330.0'' y=''85.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>A = 2 cm²</text><line x1=''40.0'' y1=''120.0'' x2=''95.0'' y2=''120.0'' stroke=''#000'' stroke-width=''1.6'' stroke-linecap=''round''/><polygon points=''87.6,123.1 95.0,120.0 87.6,116.9'' fill=''#000'' stroke=''#000'' stroke-width=''1.6'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''68.0'' y=''134.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''12'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>3 m s⁻¹</text></svg>', '["1 m s⁻¹", "9 m s⁻¹", "3 m s⁻¹", "6 m s⁻¹"]', 1, 'For an incompressible fluid A₁v₁ = A₂v₂, so 6 × 3 = 2 × v₂ and v₂ = 9 m s⁻¹. The same volume per second must pass through the narrower part, so it must move faster.', '{"0": "This divides the wrong way. The fluid speeds up in the narrow part, it does not slow down.", "2": "The speed changes because the area changes.", "3": "This adds the areas or the speeds instead of using A₁v₁ = A₂v₂."}', 1),
  ('PHY-2011', 'Physics', 'Fluid dynamics', 'Bernoulli''s effect', 'moderate', 'Markhor Prep original question', 'An ideal fluid flows steadily through the horizontal pipe shown, which narrows in the middle. At which point is the fluid pressure lowest?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''440'' height=''170'' viewBox=''0 0 440 170''><polyline points=''20.0,30.0 150.0,30.0 210.0,65.0 290.0,65.0 350.0,30.0 420.0,30.0'' fill=''none'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><polyline points=''20.0,140.0 150.0,140.0 210.0,105.0 290.0,105.0 350.0,140.0 420.0,140.0'' fill=''none'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><circle cx=''85.0'' cy=''85.0'' r=''3.5'' fill=''#000''/><text x=''99.0'' y=''85.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''15'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-weight=''bold''>X</text><circle cx=''250.0'' cy=''85.0'' r=''3.5'' fill=''#000''/><text x=''264.0'' y=''85.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''15'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-weight=''bold''>Y</text><circle cx=''385.0'' cy=''85.0'' r=''3.5'' fill=''#000''/><text x=''399.0'' y=''85.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''15'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-weight=''bold''>Z</text><line x1=''30.0'' y1=''85.0'' x2=''70.0'' y2=''85.0'' stroke=''#000'' stroke-width=''1.6'' stroke-linecap=''round''/><polygon points=''62.6,88.1 70.0,85.0 62.6,81.9'' fill=''#000'' stroke=''#000'' stroke-width=''1.6'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''50.0'' y=''70.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''12'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000''>flow</text></svg>', '["Y", "X", "Z", "The pressure is the same at X, Y and Z"]', 0, 'The fluid moves fastest at Y, where the pipe is narrowest (Av = constant). For a horizontal pipe Bernoulli''s equation gives P + ½ρv² = constant, so where the speed is highest the pressure is lowest.', '{"1": "At X the pipe is wide and the flow is slow, so the pressure is high.", "2": "Z is in a wide section like X, so the speed is low and the pressure is high.", "3": "The speed changes along the pipe, so by Bernoulli''s equation the pressure must change too."}', 1)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

