  ('PHY-2023', 'Physics', 'Electronics', 'Rectification', 'moderate', 'Markhor Prep original question', 'The graph shows the output voltage of a rectifier circuit. Compared with the a.c. input, what has happened?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''440'' height=''150'' viewBox=''0 0 440 150''><line x1=''30.0'' y1=''110.0'' x2=''430.0'' y2=''110.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><polygon points=''422.6,113.1 430.0,110.0 422.6,106.9'' fill=''#000'' stroke=''#000'' stroke-width=''1.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><line x1=''30.0'' y1=''140.0'' x2=''30.0'' y2=''15.0'' stroke=''#000'' stroke-width=''1.4'' stroke-linecap=''round''/><polygon points=''33.1,22.4 30.0,15.0 26.9,22.4'' fill=''#000'' stroke=''#000'' stroke-width=''1.4'' stroke-linejoin=''round'' stroke-linecap=''round''/><text x=''426.0'' y=''126.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-style=''italic''>t</text><polyline points=''30.0,110.0 31.3,105.0 32.6,100.0 33.9,95.0 35.2,90.1 36.5,85.3 37.8,80.6 39.1,75.9 40.4,71.5 41.7,67.1 43.0,63.0 44.3,59.0 45.6,55.2 46.9,51.7 48.2,48.4 49.5,45.3 50.8,42.5 52.1,39.9 53.4,37.6 54.7,35.6 56.0,33.9 57.3,32.5 58.6,31.4 59.9,30.6 61.2,30.2 62.5,30.0 63.8,30.2 65.1,30.6 66.4,31.4 67.7,32.5 69.0,33.9 70.3,35.6 71.6,37.6 72.9,39.9 74.2,42.5 75.5,45.3 76.8,48.4 78.1,51.7 79.4,55.2 80.7,59.0 82.0,63.0 83.3,67.1 84.6,71.5 85.9,75.9 87.2,80.6 88.5,85.3 89.8,90.1 91.1,95.0 92.4,100.0 93.7,105.0 95.0,110.0 96.3,105.0 97.6,100.0 98.9,95.0 100.2,90.1 101.5,85.3 102.8,80.6 104.1,75.9 105.4,71.5 106.7,67.1 108.0,63.0 109.3,59.0 110.6,55.2 111.9,51.7 113.2,48.4 114.5,45.3 115.8,42.5 117.1,39.9 118.4,37.6 119.7,35.6 121.0,33.9 122.3,32.5 123.6,31.4 124.9,30.6 126.2,30.2 127.5,30.0 128.8,30.2 130.1,30.6 131.4,31.4 132.7,32.5 134.0,33.9 135.3,35.6 136.6,37.6 137.9,39.9 139.2,42.5 140.5,45.3 141.8,48.4 143.1,51.7 144.4,55.2 145.7,59.0 147.0,63.0 148.3,67.1 149.6,71.5 150.9,75.9 152.2,80.6 153.5,85.3 154.8,90.1 156.1,95.0 157.4,100.0 158.7,105.0 160.0,110.0 161.3,105.0 162.6,100.0 163.9,95.0 165.2,90.1 166.5,85.3 167.8,80.6 169.1,75.9 170.4,71.5 171.7,67.1 173.0,63.0 174.3,59.0 175.6,55.2 176.9,51.7 178.2,48.4 179.5,45.3 180.8,42.5 182.1,39.9 183.4,37.6 184.7,35.6 186.0,33.9 187.3,32.5 188.6,31.4 189.9,30.6 191.2,30.2 192.5,30.0 193.8,30.2 195.1,30.6 196.4,31.4 197.7,32.5 199.0,33.9 200.3,35.6 201.6,37.6 202.9,39.9 204.2,42.5 205.5,45.3 206.8,48.4 208.1,51.7 209.4,55.2 210.7,59.0 212.0,63.0 213.3,67.1 214.6,71.5 215.9,75.9 217.2,80.6 218.5,85.3 219.8,90.1 221.1,95.0 222.4,100.0 223.7,105.0 225.0,110.0 226.3,105.0 227.6,100.0 228.9,95.0 230.2,90.1 231.5,85.3 232.8,80.6 234.1,75.9 235.4,71.5 236.7,67.1 238.0,63.0 239.3,59.0 240.6,55.2 241.9,51.7 243.2,48.4 244.5,45.3 245.8,42.5 247.1,39.9 248.4,37.6 249.7,35.6 251.0,33.9 252.3,32.5 253.6,31.4 254.9,30.6 256.2,30.2 257.5,30.0 258.8,30.2 260.1,30.6 261.4,31.4 262.7,32.5 264.0,33.9 265.3,35.6 266.6,37.6 267.9,39.9 269.2,42.5 270.5,45.3 271.8,48.4 273.1,51.7 274.4,55.2 275.7,59.0 277.0,63.0 278.3,67.1 279.6,71.5 280.9,75.9 282.2,80.6 283.5,85.3 284.8,90.1 286.1,95.0 287.4,100.0 288.7,105.0 290.0,110.0 291.3,105.0 292.6,100.0 293.9,95.0 295.2,90.1 296.5,85.3 297.8,80.6 299.1,75.9 300.4,71.5 301.7,67.1 303.0,63.0 304.3,59.0 305.6,55.2 306.9,51.7 308.2,48.4 309.5,45.3 310.8,42.5 312.1,39.9 313.4,37.6 314.7,35.6 316.0,33.9 317.3,32.5 318.6,31.4 319.9,30.6 321.2,30.2 322.5,30.0 323.8,30.2 325.1,30.6 326.4,31.4 327.7,32.5 329.0,33.9 330.3,35.6 331.6,37.6 332.9,39.9 334.2,42.5 335.5,45.3 336.8,48.4 338.1,51.7 339.4,55.2 340.7,59.0 342.0,63.0 343.3,67.1 344.6,71.5 345.9,75.9 347.2,80.6 348.5,85.3 349.8,90.1 351.1,95.0 352.4,100.0 353.7,105.0 355.0,110.0 356.3,105.0 357.6,100.0 358.9,95.0 360.2,90.1 361.5,85.3 362.8,80.6 364.1,75.9 365.4,71.5 366.7,67.1 368.0,63.0 369.3,59.0 370.6,55.2 371.9,51.7 373.2,48.4 374.5,45.3 375.8,42.5 377.1,39.9 378.4,37.6 379.7,35.6 381.0,33.9 382.3,32.5 383.6,31.4 384.9,30.6 386.2,30.2 387.5,30.0 388.8,30.2 390.1,30.6 391.4,31.4 392.7,32.5 394.0,33.9 395.3,35.6 396.6,37.6 397.9,39.9 399.2,42.5 400.5,45.3 401.8,48.4 403.1,51.7 404.4,55.2 405.7,59.0 407.0,63.0 408.3,67.1 409.6,71.5 410.9,75.9 412.2,80.6 413.5,85.3 414.8,90.1 416.1,95.0 417.4,100.0 418.7,105.0 420.0,110.0'' fill=''none'' stroke=''#000'' stroke-width=''2.4'' stroke-linejoin=''round'' stroke-linecap=''round''/></svg>', '["Only the positive half-cycles have passed", "The frequency of the humps has halved", "The output is steady d.c.", "Both halves of each cycle now drive current in the same direction"]', 3, 'This is full-wave rectification. The negative half-cycles are turned over, so every half-cycle gives a positive hump with no gaps. The humps come twice as often as the cycles of the input.', '{"0": "If only positive halves passed there would be gaps between the humps.", "1": "Full-wave rectification doubles the number of humps per second compared with the input frequency.", "2": "The output still rises and falls. It is not steady without smoothing."}', 1)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, figure, options, answer, why, wrong, mdcat, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11, s.column12, s.column13,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PHY-2024', 'Physics', 'Electronics', 'PN junction biasing', 'moderate', 'Markhor Prep original question', 'In the circuit shown, the positive terminal of the 6 V cell is marked +. What happens to lamp X when the circuit is complete?', '<svg xmlns=''http://www.w3.org/2000/svg'' width=''300'' height=''200'' viewBox=''0 0 300 200''><line x1=''50.0'' y1=''30.0'' x2=''130.0'' y2=''30.0'' stroke=''#000'' stroke-width=''2'' stroke-linecap=''round''/><line x1=''160.0'' y1=''30.0'' x2=''250.0'' y2=''30.0'' stroke=''#000'' stroke-width=''2'' stroke-linecap=''round''/><line x1=''250.0'' y1=''30.0'' x2=''250.0'' y2=''80.0'' stroke=''#000'' stroke-width=''2'' stroke-linecap=''round''/><line x1=''250.0'' y1=''120.0'' x2=''250.0'' y2=''170.0'' stroke=''#000'' stroke-width=''2'' stroke-linecap=''round''/><line x1=''250.0'' y1=''170.0'' x2=''50.0'' y2=''170.0'' stroke=''#000'' stroke-width=''2'' stroke-linecap=''round''/><line x1=''50.0'' y1=''170.0'' x2=''50.0'' y2=''106.0'' stroke=''#000'' stroke-width=''2'' stroke-linecap=''round''/><line x1=''50.0'' y1=''94.0'' x2=''50.0'' y2=''30.0'' stroke=''#000'' stroke-width=''2'' stroke-linecap=''round''/><line x1=''30.0'' y1=''94.0'' x2=''70.0'' y2=''94.0'' stroke=''#000'' stroke-width=''2.4'' stroke-linecap=''round''/><line x1=''40.0'' y1=''106.0'' x2=''60.0'' y2=''106.0'' stroke=''#000'' stroke-width=''4'' stroke-linecap=''round''/><text x=''78.0'' y=''90.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''16'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-weight=''bold''>+</text><text x=''20.0'' y=''100.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''end'' dominant-baseline=''middle'' fill=''#000''>6 V</text><polygon points=''130.0,17.0 130.0,43.0 156.0,30.0'' fill=''none'' stroke=''#000'' stroke-width=''2'' stroke-linejoin=''round'' stroke-linecap=''round''/><line x1=''158.0'' y1=''17.0'' x2=''158.0'' y2=''43.0'' stroke=''#000'' stroke-width=''2.4'' stroke-linecap=''round''/><text x=''144.0'' y=''6.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''middle'' dominant-baseline=''middle'' fill=''#000'' font-weight=''bold''>D</text><circle cx=''250.0'' cy=''100.0'' r=''20.0'' fill=''none'' stroke=''#000'' stroke-width=''2''/><line x1=''236.0'' y1=''86.0'' x2=''264.0'' y2=''114.0'' stroke=''#000'' stroke-width=''1.8'' stroke-linecap=''round''/><line x1=''236.0'' y1=''114.0'' x2=''264.0'' y2=''86.0'' stroke=''#000'' stroke-width=''1.8'' stroke-linecap=''round''/><text x=''280.0'' y=''100.0'' font-family=''Helvetica, Arial, sans-serif'' font-size=''14'' text-anchor=''start'' dominant-baseline=''middle'' fill=''#000'' font-weight=''bold''>X</text></svg>', '["It lights, because the diode is forward biased", "It stays off, because the diode is reverse biased", "It lights, but only if the battery is reversed", "It stays off, because a diode never conducts d.c."]', 0, 'Conventional current leaves the + terminal, runs along the top wire and reaches diode D on its triangle (p) side, so the diode''s arrow points the same way as the current and the p-side is at the higher potential. The diode is forward biased, its resistance is low, and current flows through the lamp.', '{"1": "Reverse bias would mean the arrow pointed against the current from the positive terminal.", "2": "Reversing the battery would reverse-bias the diode and turn the lamp off.", "3": "A forward-biased diode conducts d.c. easily. That is how it rectifies."}', 1),
  ('PHY-2025', 'Physics', 'Current electricity', 'Internal resistance', 'moderate', 'Markhor Prep original question', 'A cell of e.m.f. 12 V and internal resistance 1 Ω is connected to a 5 Ω resistor, as shown. What is the terminal potential difference across the cell?', '<svg xmlns="http://www.w3.org/2000/svg" height="334" width="245" viewBox="-18.1 -191.79999999999998 144.02 196.4"><path d="M 0.0,-0.0 L 0,-43.425 M 0,-50.175 L 0,-93.6" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M -13.499999999999998,-43.425000000000004 L 13.5,-43.425" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M -6.749999999999997,-50.175000000000004 L 6.75,-50.175" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 5.731347020009614e-15,-93.60000000000001 L 0,-122.4 L -9,-125.4 L 9,-131.4 L -9,-137.4 L 9,-143.4 L -9,-149.4 L 9,-155.4 L 0,-158.4 L 0,-187.2" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 1.1462694040019228e-14,-187.20000000000002 L 56.16,-187.2 L 112.32,-187.2" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 112.32000000000002,-187.20000000000002 L 112.32,-111.6 L 121.32,-108.6 L 103.32,-102.6 L 121.32,-96.6 L 103.32,-90.6 L 121.32,-84.6 L 103.32,-78.6 L 112.32,-75.6 L 112.32,-0" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 112.32,-0.0 L 56.16,-0 L -0,-0" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><text x="17.1" y="-61.800000000000004" dominant-baseline="central" fill="black" font-size="15" font-family="sans" text-anchor="start"><tspan x="17.1" dy="15">E = 12 V</tspan></text><text x="12.600000000000007" y="-155.4" dominant-baseline="central" fill="black" font-size="15" font-family="sans" text-anchor="start"><tspan x="12.600000000000007" dy="15">r = 1 Ω</tspan></text><text x="99.72" y="-108.60000000000001" dominant-baseline="central" fill="black" font-size="15" font-family="sans" text-anchor="end"><tspan x="99.72" dy="15">R = 5 Ω</tspan></text></svg>', '["12 V", "2 V", "6 V", "10 V"]', 3, 'The current is I = E ÷ (R + r) = 12 ÷ (5 + 1) = 2 A. The terminal p.d. is V = IR = 2 × 5 = 10 V, which equals E − Ir = 12 − 2.', '{"0": "12 V is the e.m.f. Some of it is lost across the internal resistance when current flows.", "1": "2 V is the ''lost volts'' across the internal resistance, not the terminal p.d.", "2": "This splits the e.m.f. equally, but the resistors are not equal."}', 1),
  ('PHY-2026', 'Physics', 'Current electricity', 'Maximum power transfer', 'hard', 'Markhor Prep original question', 'The 5 Ω resistor in the circuit shown is replaced by a variable resistor. What value of external resistance takes the most power from the 12 V, 1 Ω cell?', '<svg xmlns="http://www.w3.org/2000/svg" height="334" width="245" viewBox="-18.1 -191.79999999999998 144.02 196.4"><path d="M 0.0,-0.0 L 0,-43.425 M 0,-50.175 L 0,-93.6" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M -13.499999999999998,-43.425000000000004 L 13.5,-43.425" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M -6.749999999999997,-50.175000000000004 L 6.75,-50.175" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 5.731347020009614e-15,-93.60000000000001 L 0,-122.4 L -9,-125.4 L 9,-131.4 L -9,-137.4 L 9,-143.4 L -9,-149.4 L 9,-155.4 L 0,-158.4 L 0,-187.2" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 1.1462694040019228e-14,-187.20000000000002 L 56.16,-187.2 L 112.32,-187.2" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 112.32000000000002,-187.20000000000002 L 112.32,-111.6 L 121.32,-108.6 L 103.32,-102.6 L 121.32,-96.6 L 103.32,-90.6 L 121.32,-84.6 L 103.32,-78.6 L 112.32,-75.6 L 112.32,-0" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 112.32,-0.0 L 56.16,-0 L -0,-0" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><text x="17.1" y="-61.800000000000004" dominant-baseline="central" fill="black" font-size="15" font-family="sans" text-anchor="start"><tspan x="17.1" dy="15">E = 12 V</tspan></text><text x="12.600000000000007" y="-155.4" dominant-baseline="central" fill="black" font-size="15" font-family="sans" text-anchor="start"><tspan x="12.600000000000007" dy="15">r = 1 Ω</tspan></text><text x="99.72" y="-108.60000000000001" dominant-baseline="central" fill="black" font-size="15" font-family="sans" text-anchor="end"><tspan x="99.72" dy="15">R = 5 Ω</tspan></text></svg>', '["5 Ω", "1 Ω", "12 Ω", "As small as possible"]', 1, 'Maximum power is delivered to the load when the load resistance equals the internal resistance, R = r = 1 Ω. Then I = 12 ÷ 2 = 6 A and P = I²R = 36 W, more than the 20 W taken by 5 Ω.', '{"0": "5 Ω takes I = 2 A and P = 20 W, which is less than with 1 Ω.", "2": "A larger resistance reduces the current so much that the power drops.", "3": "As R tends to zero the current is large but almost no p.d. is across the load, so the power tends to zero."}', 1),
  ('PHY-2027', 'Physics', 'Current electricity', 'Series and parallel resistors', 'moderate', 'Markhor Prep original question', 'In the circuit shown, what is the current through the 3 Ω resistor? (The battery has no internal resistance.)', '<svg xmlns="http://www.w3.org/2000/svg" height="226" width="372" viewBox="-18.1 -125.8 218.9 133.1"><path d="M 0.0,-0.0 L 0,-43.425 M 0,-50.175 L 0,-93.6" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M -13.499999999999998,-43.425000000000004 L 13.5,-43.425" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M -6.749999999999997,-50.175000000000004 L 6.75,-50.175" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 5.731347020009614e-15,-93.60000000000001 L 28.8,-93.6 L 31.8,-102.6 L 37.8,-84.6 L 43.8,-102.6 L 49.8,-84.6 L 55.8,-102.6 L 61.8,-84.6 L 64.8,-93.6 L 93.6,-93.6" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 93.60000000000001,-93.60000000000001 L 93.6,-64.8 L 102.6,-61.8 L 84.6,-55.8 L 102.6,-49.8 L 84.6,-43.8 L 102.6,-37.8 L 84.6,-31.8 L 93.6,-28.8 L 93.6,-0" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 93.60000000000001,-93.60000000000001 L 140.4,-93.6 L 187.2,-93.6" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 187.20000000000002,-93.60000000000001 L 187.2,-64.8 L 196.2,-61.8 L 178.2,-55.8 L 196.2,-49.8 L 178.2,-43.8 L 196.2,-37.8 L 178.2,-31.8 L 187.2,-28.8 L 187.2,-0" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 187.2,-0.0 L 140.4,-0 L 93.6,-0" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><path d="M 93.59999999999997,-1.1462694040019228e-14 L 46.8,-0 L -0,-0" style="stroke:black;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;" /><text x="17.1" y="-61.800000000000004" dominant-baseline="central" fill="black" font-size="15" font-family="sans" text-anchor="start"><tspan x="17.1" dy="15">12 V</tspan></text><text x="46.80000000000001" y="-121.2" dominant-baseline="ideographic" fill="black" font-size="15" font-family="sans" text-anchor="middle"><tspan x="46.80000000000001" dy="15">2 Ω</tspan></text><text x="106.19999999999999" y="-61.800000000000004" dominant-baseline="central" fill="black" font-size="15" font-family="sans" text-anchor="start"><tspan x="106.19999999999999" dy="15">6 Ω</tspan></text><text x="174.6" y="-61.800000000000004" dominant-baseline="central" fill="black" font-size="15" font-family="sans" text-anchor="end"><tspan x="174.6" dy="15">3 Ω</tspan></text><circle cx="93.6" cy="-93.6" r="2.7" style="stroke:black;fill:black;stroke-width:1.8;" /><circle cx="93.6" cy="-0" r="2.7" style="stroke:black;fill:black;stroke-width:1.8;" /></svg>', '["3 A", "1 A", "4 A", "2 A"]', 3, '6 Ω and 3 Ω in parallel give 6 × 3 ÷ (6 + 3) = 2 Ω. The total is 2 + 2 = 4 Ω, so the battery current is 12 ÷ 4 = 3 A. The p.d. across the parallel pair is 3 × 2 = 6 V, so the current in 3 Ω is 6 ÷ 3 = 2 A.', '{"0": "3 A is the total current from the battery. It splits between the two branches.", "1": "1 A is the current in the 6 Ω branch.", "2": "4 A would need the full 12 V across the 3 Ω resistor."}', 1)
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

