FROM (VALUES
  ('LR-1121', 'Logical Reasoning', 'Patterns and sequences', 'Jumbled words', 'hard', 'Markhor Prep original question', 'Rearrange the letters of NRBIA to make a word. Which group does that word belong to?', '', '["Planets", "Parts of the body", "Rivers", "Metals"]', 1, 'NRBIA rearranges to BRAIN, a part of the body.', '{"0": "No planet''s name uses exactly these letters.", "2": "No major river''s name uses exactly these letters.", "3": "No metal''s name uses exactly these letters."}', 1),
  ('LR-1122', 'Logical Reasoning', 'Patterns and sequences', 'Word meanings', 'moderate', 'Markhor Prep original question', 'Choose the word closest in meaning to OBSOLETE.', '', '["Outdated", "Obvious", "Hidden", "Stubborn"]', 0, 'Obsolete means no longer in use, out of date.', '{"1": "Obvious means easy to see; it sounds similar but means something else.", "2": "Hidden means out of sight.", "3": "Stubborn describes a person who won''t change their mind."}', 1),
  ('LR-1123', 'Logical Reasoning', 'Patterns and sequences', 'Word meanings', 'moderate', 'Markhor Prep original question', 'Choose the word most nearly opposite in meaning to SCARCE.', '', '["Rare", "Expensive", "Small", "Plentiful"]', 3, 'Scarce means in short supply, so its opposite is plentiful.', '{"0": "Rare means nearly the same as scarce.", "1": "Scarce things are often expensive, but expensive is not the opposite.", "2": "Small describes size, not supply."}', 1),
  ('LR-1124', 'Logical Reasoning', 'Patterns and sequences', 'Word meanings', 'hard', 'Markhor Prep original question', 'Choose the word closest in meaning to METICULOUS.', '', '["Careless", "Quick", "Thorough", "Nervous"]', 2, 'Meticulous means paying very careful attention to every detail, the same as thorough.', '{"0": "Careless is the opposite of meticulous.", "1": "Quick says nothing about care over detail.", "3": "Nervous describes worry, not care over detail."}', 1)
) AS s
